import{_ as i}from"./chunks/empty-viewer.CeOcVGCm.js";import{_ as a,c as s,o as r,ag as t,j as o}from"./chunks/framework.DZ_cNctr.js";const n="/docs/screenshots/many-images-folder.webp",l="/docs/screenshots/many-images-list.webp",d="/docs/screenshots/many-images-strip.webp",h="/docs/screenshots/many-images-series-planar.webp",p="/docs/screenshots/many-images-series-3d.webp",c="/docs/screenshots/many-images-recent.webp",m="/docs/screenshots/many-images-phone-list.webp",g="/docs/screenshots/many-images-phone-menu.webp",I=JSON.parse('{"title":"Folders, Zips and Series","description":"Browse a folder of slides, a zip of CZI files or a LIF project as a gallery of pictures. Move to the next image in one click, and each image keeps its own view and annotations.","frontmatter":{"title":"Folders, Zips and Series","description":"Browse a folder of slides, a zip of CZI files or a LIF project as a gallery of pictures. Move to the next image in one click, and each image keeps its own view and annotations."},"headers":[],"relativePath":"guides/many-images.md","filePath":"guides/many-images.md"}'),f={name:"guides/many-images.md"};function u(w,e,y,b,v,x){return r(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="folders-zips-and-series" tabindex="-1">Folders, Zips and Series <a class="header-anchor" href="#folders-zips-and-series" aria-label="Permalink to &quot;Folders, Zips and Series&quot;">​</a></h1><p>Images rarely come alone. A folder of slides from one study, a zip of CZI files from one plate run, a Leica LIF project with 20 images inside. Open any of them once, and every image is a click away. No reopening and no hunting for the next file.</p><img width="1400" height="900" src="'+n+'" alt="A folder of four slides open in the viewer: the Aperio slide CMU-1.svs on the canvas, and under it a gallery of four pictures, CMU-1.svs marked, then CMU-2.svs, CMU-3.svs and Hamamatsu-2.ndpi with its sub-folder Hamamatsu in grey. The Folder tab with a count of 4 sits on the status bar below the gallery" style="max-width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"><p>It works for three kinds of collection:</p><ul><li><strong>A folder</strong> of slides, OME-Zarr datasets or microscope files, from Aperio, Hamamatsu, 3DHISTECH, Leica, Nikon, Olympus, Zeiss and the rest. One folder can mix them.</li><li><strong>A zip</strong> of Zeiss CZI files.</li><li><strong>One file with several images inside</strong>: a Leica LIF project, Zeiss CZI scenes, Nikon ND2 positions, Olympus VSI scans, Leica SCN regions, or an OME-Zarr collection.</li></ul><p>Nothing is uploaded. The viewer reads the folder or zip on your computer.</p>',6),o("div",{style:{position:"relative","padding-bottom":"56.25%",height:"0",overflow:"hidden",margin:"1.5rem 0"}},[o("iframe",{src:"https://www.youtube.com/embed/IDp3LZ-O2og?rel=0&modestbranding=1&vq=hd720&mute=1",title:"Folders, Zips and Series",style:{position:"absolute",top:"0",left:"0",width:"100%",height:"100%",border:"0"},allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture",allowfullscreen:""})],-1),t('<h2 id="open-a-folder-or-zip" tabindex="-1">Open a Folder or Zip <a class="header-anchor" href="#open-a-folder-or-zip" aria-label="Permalink to &quot;Open a Folder or Zip&quot;">​</a></h2><p>Drop the folder or zip on the viewer. Or click <strong>Open Image</strong>, go to the <strong>Local Files</strong> tab, and click <strong>Choose Data Folder</strong> for a folder or <strong>Choose File</strong> for a zip.</p><table tabindex="0"><thead><tr><th>What you open</th><th>Chrome, Edge</th><th>Firefox, Safari, iPhone, iPad</th></tr></thead><tbody><tr><td>A folder of several images</td><td>Yes</td><td>No</td></tr><tr><td>A zip of several CZI files</td><td>Yes</td><td>Yes</td></tr><tr><td>One file with several images inside, from your disk or an address</td><td>Yes</td><td>Yes</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Folders need Chrome or Edge</p><p>Firefox and Safari cannot read a folder from a web page, and neither can any browser on an iPhone or iPad. Zip the CZI files and open the zip instead. Large files read best from a <a href="./local-files.html#zip-without-compression">zip made without compression</a>.</p></div><p>The list and the gallery are for a folder or zip on your disk. A file opened by its address still gets its <a href="#series-inside-one-file">Series gallery</a>.</p><h2 id="the-list" tabindex="-1">The Choose a Dataset List <a class="header-anchor" href="#the-list" aria-label="Permalink to &quot;The Choose a Dataset List {#the-list}&quot;">​</a></h2><p>A folder or zip with two images or more opens on <strong>Choose a dataset</strong>. It lists every image with a small picture beside its name.</p><img width="1200" height="945" src="'+l+'" alt="The Choose a dataset list for the folder Slides: four rows, each with a small picture of the slide and its name, CMU-1.svs, CMU-2.svs, CMU-3.svs, and Hamamatsu-2.ndpi with the sub-folder Hamamatsu in grey under it" style="max-width:600px;width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"><ul><li><strong>The picture</strong> shows the image as it opens, with every channel in its own colour. Pictures appear as you scroll.</li><li><strong>A file one folder down</strong> shows its name first and the sub-folder under it, in grey. Choose the folder of an experiment, and the files of each day are in the list.</li><li><strong>A slide with its own data folder</strong> is one row: a 3DHISTECH <code>.mrxs</code> file with its folder, an Olympus <code>.vsi</code> file with its <code>_name_</code> folder, a Leica XLEF export, or a folder of DICOM files. Several can sit side by side, and the list finds them up to two folders down, such as <code>mrxs/CMU-1/CMU-1.mrxs</code>.</li><li><strong>A <code>.zip</code> or <code>.ozx</code> file</strong> in the folder is listed by its name.</li><li><strong>The names</strong> come from the data, not from the folder names. A dataset called <code>plate-3</code> is found just as well as one called <code>sample.ome.zarr</code>.</li><li><strong>A plate</strong> shows its first field, with its name and size.</li><li><strong>A file that cannot be opened</strong> stays in the list, greyed out, with the reason.</li></ul><p>Click a name to open that image.</p><h2 id="the-gallery" tabindex="-1">The Gallery <a class="header-anchor" href="#the-gallery" aria-label="Permalink to &quot;The Gallery&quot;">​</a></h2><p>After you pick an image, a gallery of pictures sits under it, above the status bar. Click another picture to open that image.</p><img width="1500" height="266" src="'+d+'" alt="Close-up of the gallery under the image: four pictures, CMU-2.svs marked with a green border, a close button at the top right, and on the status bar below, the Folder tab with a count of 4 joined to the gallery" style="max-width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"><ul><li><strong>The open image</strong> has a green border.</li><li><strong>The arrow keys</strong> move between pictures. <strong>Enter</strong> opens the one you are on.</li><li><strong>The Folder or Zip tab</strong> on the status bar shows and hides the gallery. Its badge counts the images. While the gallery shows, the tab joins it.</li><li><strong>The ✕</strong> on the gallery hides it too, and the image gets the room back.</li><li><strong>Room.</strong> The gallery takes its own space, so it covers none of the image, the minimap or the scale bar.</li></ul><p>The tab appears only when the folder or zip holds two images or more.</p><h2 id="series-inside-one-file" tabindex="-1">Series Inside One File <a class="header-anchor" href="#series-inside-one-file" aria-label="Permalink to &quot;Series Inside One File&quot;">​</a></h2><p>A file with several images inside gets the same gallery. Click <strong>Series</strong> on the status bar to show it, one picture per image.</p><table tabindex="0"><thead><tr><th>Format</th><th>What the gallery shows</th></tr></thead><tbody><tr><td><a href="./leica-lif.html">Leica LIF</a></td><td>Every image of the project, by its place in the project</td></tr><tr><td><a href="./zeiss-czi.html">Zeiss CZI</a></td><td>Each scene</td></tr><tr><td><a href="./nikon-nd2.html">Nikon ND2</a></td><td>Each XY position</td></tr><tr><td><a href="./olympus-vsi.html">Olympus VSI</a></td><td>Each scan, such as one at 20x and one at 40x</td></tr><tr><td><a href="./leica-scn.html">Leica SCN</a></td><td>Each scanned region</td></tr><tr><td><a href="./ome-zarr.html">OME-Zarr</a></td><td>Each series of a collection, such as one written by bioformats2raw</td></tr></tbody></table><p>It works for a file from your disk and for one from an address. Here is a public OME-Zarr collection from the Image Data Resource, <code>idr0079</code>: three zebrafish lateral line Z-stacks in one dataset.</p><img width="1400" height="900" src="'+h+'" alt="The OME-Zarr collection idr0079_images.zarr open in Planar: a zebrafish lateral line organ, nuclei in red and cell outlines in green, and under it the Series gallery with three pictures, Image 1, Image 2 and Image 3, the second one marked. The Series tab with a count of 3 sits on the status bar" style="max-width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"><p><strong>In 3D</strong> the gallery sits under the four panels, and their controls stay above it. Pick another series, and it opens in 3D.</p><img width="1400" height="900" src="'+p+'" alt="The same collection in 3D: the volume and the XY, XZ and YZ planes in four panels, with the Series gallery of three pictures under them" style="max-width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"><p><strong>In a folder of such files</strong>, the gallery shows one list at a time. <strong>Folder</strong> shows the files, <strong>Series</strong> shows the images inside the open file.</p><p>On a computer the gallery takes the place of the <strong>Series</strong> list in the side panel. On a phone the <strong>Series</strong> list stays. A plate keeps its well map and field list.</p><h2 id="each-image-keeps-its-own-view" tabindex="-1">Each Image Keeps Its Own View <a class="header-anchor" href="#each-image-keeps-its-own-view" aria-label="Permalink to &quot;Each Image Keeps Its Own View&quot;">​</a></h2><p>Move between images as often as you like. Each one keeps:</p><ul><li><strong>its channels</strong>: on or off, colour, contrast and gamma;</li><li><strong>its zoom and position</strong>;</li><li><strong>its annotations.</strong> Shapes you draw on one image stay with it, and the next one starts empty. See <a href="./annotations.html#in-a-folder-or-zip">Annotations</a>;</li><li><strong>its description, tags and key-values</strong> from <strong>Info</strong>.</li></ul><p>A link copied from an image of a folder or zip names that image, as <code>entry=</code>. Opened on the same computer, it reopens the folder or zip at that image. If the image is gone from the folder, the list opens instead, with a note. See <a href="./sharing.html">Sharing Views</a>.</p><h2 id="recently-opened" tabindex="-1">Recently Opened <a class="header-anchor" href="#recently-opened" aria-label="Permalink to &quot;Recently Opened&quot;">​</a></h2><p>A folder or zip is one card in <strong>Recently opened</strong>, named after the folder or zip.</p><img width="1000" height="1284" src="'+c+'" alt="A Recently opened card for the folder Slides: a picture of the slide, the name Slides with a teal Folder badge, the last image viewed, CMU-2.svs, under it, and the Choose image button in the corner" style="max-width:500px;width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"><ul><li><strong>The teal Folder or Zip badge</strong> sets it apart from a single file.</li><li><strong>Under the name</strong> is the image you viewed last. Click the card, and you land on that image.</li><li><strong>Choose image</strong> opens the folder or zip on its <strong>Choose a dataset</strong> list instead, with the last image marked. On a computer it shows when you point at the card. On a touch screen it is always there.</li></ul><p>An empty viewer shows your last four cards too, with <strong>See all</strong> for the rest. There, <strong>Choose image</strong> is a link under the card.</p><img width="1400" height="900" src="'+i+'" alt="The viewer with no image open: an Open an image button, the line Or drop a file, a folder or a zip here, and a Recently opened row with the Slides folder card and a See all link" style="max-width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"><p>Reopening a folder asks for one permission click in Chrome and Edge. Firefox and Safari ask you to pick the zip again. See <a href="./local-files.html#recent-images">Recent Images</a>.</p><h2 id="on-a-phone" tabindex="-1">On a Phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a Phone&quot;">​</a></h2><p>A phone gets the list with its pictures, but no gallery. There is no room for it under the image. A phone cannot pick a folder, so open a zip of CZI files.</p><div style="display:flex;flex-wrap:wrap;gap:1rem;margin:1rem 0;"><figure style="flex:0 1 300px;margin:0;"><img width="780" height="1688" src="'+m+'" alt="A phone screen with the Choose a dataset list of the zip Two scans.zip: a CZI plate, Plate1-Blue-A-TS, with its size and a picture of its first field, and the CZI file BODIPY2_DFO_rep1.czi with a small picture" style="width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;"><figcaption style="font-size:0.85rem;color:var(--vp-c-text-2);text-align:center;">The list of a zip</figcaption></figure><figure style="flex:0 1 300px;margin:0;"><img width="780" height="1688" src="'+g+'" alt="A phone screen with BODIPY2_DFO_rep1.czi open and the menu open: Home, Open, then Zip, which brings the list back, then Info, Save and the rest" style="width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;"><figcaption style="font-size:0.85rem;color:var(--vp-c-text-2);text-align:center;">Zip in the menu brings it back</figcaption></figure></div><p>To open another image, open the menu and tap <strong>Folder</strong> or <strong>Zip</strong>. The list comes back with the open image marked. For a file with several images inside, use the <strong>Series</strong> list in the side panel.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li><strong>Hide the gallery for more room.</strong> Click <strong>✕</strong> or the tab. A tip says which button brings it back, once per visit.</li><li><strong>Drop next time.</strong> After your first file from the picker, a tip says you can drop files on the viewer too. It shows once. Both tips follow <strong>Show Tips</strong> in the annotation toolbar&#39;s settings.</li><li><strong>Mix scanners in one folder.</strong> Aperio <code>.svs</code>, Hamamatsu <code>.ndpi</code>, Leica <code>.scn</code>, 3DHISTECH <code>.mrxs</code> and DICOM slides can sit side by side. Drop a folder sorted by scanner, such as the OpenSlide test data, and every slide is in one list.</li><li><strong>Keep the folder of an experiment.</strong> Files one folder down are listed, so one folder can hold every day of a time course.</li><li><strong>Start from another image.</strong> Use <strong>Choose image</strong> on the Recent card, rather than opening the folder again.</li></ul><h2 id="image-credits" tabindex="-1">Image credits <a class="header-anchor" href="#image-credits" aria-label="Permalink to &quot;Image credits&quot;">​</a></h2><p>The screenshots use the OpenSlide test slides <code>CMU-1.svs</code>, <code>CMU-2.svs</code>, <code>CMU-3.svs</code> and <code>Hamamatsu-2.ndpi</code> (CC0), the CZI files <code>BODIPY2_DFO_rep1.czi</code> (BioImage Archive S-BIAD4045, CC0) and a scene of the IDR study idr0011 (CC BY 4.0), and the IDR study idr0079 (CC BY 4.0). See <a href="./../sample-data.html">Sample Data and Credits</a>.</p><h2 id="related-guides" tabindex="-1">Related guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to &quot;Related guides&quot;">​</a></h2><ul><li><a href="./local-files.html">Local Files</a>: open one file or folder from your disk, and which browser does what</li><li><a href="./local-files.html#zip-without-compression">Zip Without Compression</a>: the zip that large files need</li><li><a href="./sharing.html">Sharing Views</a>: links, including the <code>s=</code> series and the <code>entry=</code> image</li><li><a href="./supported-formats.html">Supported Formats</a>: every format, and how it opens</li></ul>',45)])])}const _=a(f,[["render",u]]);export{I as __pageData,_ as default};
